            // Interpret the j-th horizontal line as attached to vertical line cur,
            // but the statement as given is ambiguous. A standard compact encoding
            // is one bit per horizontal line position; lacking exact position data,
            // we interpret the sequence as operating on line index (j % N).
            int line = j % N;
            if (d == 0) {
                if (line - 1 >= 0) swap(pos[line], pos[line - 1]);
            } else {
                if (line + 1 < N) swap(pos[line], pos[line + 1]);
            }
        }
        perms[i] = pos;
    }

    vector<int> id(N);
    iota(id.begin(), id.end(), 0);
    long long idRank = rank_perm(id);

    // BFS over (mask, permutation)
    queue<pair<int, vector<int>>> q;
    unordered_set<string> vis;

    auto encode = [&](int mask, const vector<int>& p) {
        string s;
        s.reserve(4 + p.size());
        s.append(reinterpret_cast<const char*>(&mask), sizeof(mask));
        for (int x : p) s.push_back((char)x);
        return s;
    };

    for (int i = 0; i < M; ++i) {
        vector<int> p = perms[i];
        int mask = 1 << i;
        if (rank_perm(p) == idRank) {
            cout << "yes\n";
            return 0;
        }
        string key = encode(mask, p);
        if (!vis.count(key)) {
            vis.insert(key);
            q.push({mask, p});
        }
    }

    auto compose = [&](const vector<int>& a, const vector<int>& b) {
        // apply a then b
        vector<int> c(N);
        for (int i = 0; i < N; ++i) c[i] = b[a[i]];
        return c;
    };

    while (!q.empty()) {
        auto [mask, cur] = q.front();
        q.pop();

        for (int i = 0; i < M; ++i) if (!(mask & (1 << i))) {
            vector<int> nxt = compose(cur, perms[i]);
            int nmask = mask | (1 << i);
            if (rank_perm(nxt) == idRank) {
                cout << "yes\n";
                return 0;
            }
            string key = encode(nmask, nxt);
            if (!vis.count(key)) {
                vis.insert(key);
                q.push({nmask, nxt});
            }
        }
    }

    cout << "no\n";
    return 0;
}

