public class Main {

    static class Amidakuji {
        int n; // number of vertical lines
        int[] perm; // permutation representing the lottery

        Amidakuji(int n, List<Integer> moves) {
            this.n = n;
            this.perm = new int[n];
            for (int i = 0; i < n; i++) perm[i] = i;
            int[] pos = new int[n];
            for (int i = 0; i < n; i++) pos[i] = i;

            for (int move : moves) {
                // move is the index of the left vertical line of the horizontal bar
                // swap pos[move] and pos[move+1]
                int tmp = pos[move];
                pos[move] = pos[move+1];
                pos[move+1] = tmp;
            }

            // now pos[i] = where the person starting at i ends up
            for (int i = 0; i < n; i++) {
                perm[pos[i]] = i;
            }
        }
    }

    // Multiply two permutations: result = a * b (apply b then a)
    static int[] multiply(int[] a, int[] b) {
        int n = a.length;
        int[] res = new int[n];
        for (int i = 0; i < n; i++) {
            res[i] = a[b[i]];
        }
        return res;
    }

    // Check if permutation is identity
    static boolean isIdentity(int[] p) {
        for (int i = 0; i < p.length; i++) {
            if (p[i] != i) return false;
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            String[] parts = line.split(" ");
            int N = Integer.parseInt(parts[0]);
            int M = Integer.parseInt(parts[1]);

            List<Amidakuji> lotteries = new ArrayList<>();
            boolean possible = false;

            for (int i = 0; i < M; i++) {
                line = br.readLine().trim();
                String[] data = line.split(" ");
                int n = Integer.parseInt(data[0]);
                int h = Integer.parseInt(data[1]);
                List<Integer> moves = new ArrayList<>();
                for (int j = 0; j < h; j++) {
                    moves.add(Integer.parseInt(data[2 + j]));
                }
                Amidakuji a = new Amidakuji(n, moves);
                lotteries.add(a);

                // Check if this single lottery is already good
                if (isIdentity(a.perm)) {
                    possible = true;
                }
            }

            if (!possible) {
                // Try combinations of two lotteries with same n
                // Group by n
                Map<Integer, List<int[]>> permsBySize = new HashMap<>();
                for (Amidakuji a : lotteries) {
                    permsBySize.computeIfAbsent(a.n, k -> new ArrayList<>()).add(a.perm);
                }

                for (List<int[]> perms : permsBySize.values()) {
                    int n = perms.get(0).length;
                    // Check if any single is identity already done
                    // Check pairs
                    for (int i = 0; i < perms.size() && !possible; i++) {
                        for (int j = i; j < perms.size() && !possible; j++) {
                            int[] prod = multiply(perms.get(i), perms.get(j));
                            if (isIdentity(prod)) {
                                possible = true;
                            }
                        }
                    }
                    // Check if any permutation has order 2 (its square is identity)
                    if (!possible) {
                        for (int[] p : perms) {
                            int[] sq = multiply(p, p);
                            if (isIdentity(sq)) {
                                possible = true;
                                break;
                            }
                        }
                    }
                }
            }

            System.out.println(possible ? "yes" : "no");

            // Skip remaining lines? No, we read all M lines already in loop
        }
        br.close();
    }
}

