    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();

        DSU dsu = new DSU(N);

        for (int i = 0; i < M; i++) {
            int k = fs.nextInt();
            int[] a = new int[k];
            for (int j = 0; j < k; j++) a[j] = fs.nextInt();

            int[] p = new int[N];
            for (int j = 0; j < N; j++) p[j] = j;

            for (int j = 0; j < k; j++) {
                if (a[j] == 1) {
                    if (j + 1 < N) {
                        int tmp = p[j];
                        p[j] = p[j + 1];
                        p[j + 1] = tmp;
                    }
                }
            }

            for (int j = 0; j < N; j++) {
                dsu.union(j, p[j]);
            }
        }

        int root = dsu.find(0);
        boolean ok = true;
        for (int i = 1; i < N; i++) {
            if (dsu.find(i) != root) {
                ok = false;
                break;
            }
        }

        System.out.println(ok ? "yes" : "no");
    }

    static class DSU {
        int[] p, r;

        DSU(int n) {
            p = new int[n];
            r = new int[n];
            for (int i = 0; i < n; i++) p[i] = i;
        }

        int find(int x) {
            if (p[x] != x) p[x] = find(p[x]);
            return p[x];
        }

        void union(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return;
            if (r[a] < r[b]) {
                p[a] = b;
            } else if (r[a] > r[b]) {
                p[b] = a;
            } else {
                p[b] = a;
                r[a]++;
            }
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

